    s->codec_id= s->avctx->codec_id= CODEC_ID_MPEG2VIDEO;

    s->avctx->sub_id = 2; /* indicates mpeg2 found */



    if(s->avctx->debug & FF_DEBUG_PICT_INFO)

        av_log(s->avctx, AV_LOG_DEBUG, "profile: %d, level: %d vbv buffer: %d, bitrate:%d\n", 

