static void init_2d_vlc_rl(RLTable *rl)

{

    int i;



    init_vlc(&rl->vlc, TEX_VLC_BITS, rl->n + 2, 

             &rl->table_vlc[0][1], 4, 2,

             &rl->table_vlc[0][0], 4, 2);





