    /* All CPUs start halted.  CPU0 is unhalted from the machine level

     * reset code and the rest are explicitly started up by the guest

     * using an RTAS call */

    cs->halted = 1;



    env->spr[SPR_HIOR] = 0;



    env->external_htab = (uint8_t *)spapr->htab;

