static AVBufferRef *pool_alloc_buffer(AVBufferPool *pool)

{

    BufferPoolEntry *buf;

    AVBufferRef     *ret;



    ret = pool->alloc(pool->size);

    if (!ret)

        return NULL;



    buf = av_mallocz(sizeof(*buf));

    if (!buf) {

