static AVStream *add_av_stream1(FFServerStream *stream,

                                AVCodecContext *codec, int copy)

{

    AVStream *fst;



    if(stream->nb_streams >= FF_ARRAY_ELEMS(stream->streams))

        return NULL;



    fst = av_mallocz(sizeof(AVStream));

    if (!fst)

        return NULL;

    if (copy) {

        fst->codec = avcodec_alloc_context3(codec->codec);

        if (!fst->codec) {

            av_free(fst);

            return NULL;

        }

        avcodec_copy_context(fst->codec, codec);

    } else

        /* live streams must use the actual feed's codec since it may be

         * updated later to carry extradata needed by them.

         */

        fst->codec = codec;



    fst->priv_data = av_mallocz(sizeof(FeedData));


    fst->index = stream->nb_streams;

    avpriv_set_pts_info(fst, 33, 1, 90000);

    fst->sample_aspect_ratio = codec->sample_aspect_ratio;

    stream->streams[stream->nb_streams++] = fst;

    return fst;

}

static void draw_slice(AVFilterLink *inlink, int y, int h, int slice_dir)

{

    FadeContext *fade = inlink->dst->priv;

    AVFilterBufferRef *outpic = inlink->cur_buf;

    uint8_t *p;

    int i, j, plane;



    if (fade->factor < 65536) {

        /* luma or rgb plane */

        for (i = 0; i < h; i++) {

            p = outpic->data[0] + (y+i) * outpic->linesize[0];

            for (j = 0; j < inlink->w * fade->bpp; j++) {

                /* fade->factor is using 16 lower-order bits for decimal

                 * places. 32768 = 1 << 15, it is an integer representation

                 * of 0.5 and is for rounding. */

                *p = (*p * fade->factor + 32768) >> 16;

                p++;

            }

        }



        if (outpic->data[0] && outpic->data[1]) {

            /* chroma planes */

            for (plane = 1; plane < 3; plane++) {

                for (i = 0; i < h; i++) {

                    p = outpic->data[plane] + ((y+i) >> fade->vsub) * outpic->linesize[plane];

                    for (j = 0; j < inlink->w >> fade->hsub; j++) {

                        /* 8421367 = ((128 << 1) + 1) << 15. It is an integer

                         * representation of 128.5. The .5 is for rounding

                         * purposes. */

                        *p = ((*p - 128) * fade->factor + 8421367) >> 16;

                        p++;

                    }

                }

            }

        }

    }



    avfilter_draw_slice(inlink->dst->outputs[0], y, h, slice_dir);

}

