static void vc1_h_overlap_c(uint8_t* src, int stride)

{

    int i;

    int a, b, c, d;

    int d1, d2;

    int rnd = 1;

    for(i = 0; i < 8; i++) {

        a = src[-2];

        b = src[-1];

        c = src[0];

        d = src[1];

        d1 = (a - d + 3 + rnd) >> 3;

        d2 = (a - d + b - c + 4 - rnd) >> 3;



        src[-2] = a - d1;

        src[-1] = b - d2;

        src[0] = c + d2;

        src[1] = d + d1;

        src += stride;

        rnd = !rnd;

    }

}

