{

    int i;



    if (!(pte0 & HPTE64_V_LARGE)) {

        if (sps->page_shift != 12) {

            /* 4kiB page in a non 4kiB segment */

            return 0;

        }

        /* Normal 4kiB page */

        return 12;

    }



    for (i = 0; i < PPC_PAGE_SIZES_MAX_SZ; i++) {

        const struct ppc_one_page_size *ps = &sps->enc[i];

        uint64_t mask;



        if (!ps->page_shift) {

