static void pxa2xx_ssp_fifo_update(PXA2xxSSPState *s)

{

    s->sssr &= ~(0xf << 12);	/* Clear RFL */

    s->sssr &= ~(0xf << 8);	/* Clear TFL */

    s->sssr &= ~SSSR_TNF;

    if (s->enable) {

