ssize_t qemu_put_compression_data(QEMUFile *f, const uint8_t *p, size_t size,

                                  int level)

{

    ssize_t blen = IO_BUF_SIZE - f->buf_index - sizeof(int32_t);



    if (blen < compressBound(size)) {

        return 0;

    }

    if (compress2(f->buf + f->buf_index + sizeof(int32_t), (uLongf *)&blen,

                  (Bytef *)p, size, level) != Z_OK) {

        error_report("Compress Failed!");

        return 0;

    }

    qemu_put_be32(f, blen);

    f->buf_index += blen;

    return blen + sizeof(int32_t);

}

void muls64(int64_t *phigh, int64_t *plow, int64_t a, int64_t b)

{

#if defined(__x86_64__)

    __asm__ ("imul %0\n\t"

             : "=d" (*phigh), "=a" (*plow)

             : "a" (a), "0" (b)

             );

#else

    int64_t ph;

    uint64_t pm1, pm2, pl;



    pl = (uint64_t)((uint32_t)a) * (uint64_t)((uint32_t)b);

    pm1 = (a >> 32) * (uint32_t)b;

    pm2 = (uint32_t)a * (b >> 32);

    ph = (a >> 32) * (b >> 32);



    ph += (int64_t)pm1 >> 32;

    pm1 = (uint64_t)((uint32_t)pm1) + pm2 + (pl >> 32);



    *phigh = ph + ((int64_t)pm1 >> 32);

    *plow = (pm1 << 32) + (uint32_t)pl;

#endif

}

static void qio_channel_websock_handshake_send_res_ok(QIOChannelWebsock *ioc,

                                                      const char *key,

                                                      Error **errp)

{

    char combined_key[QIO_CHANNEL_WEBSOCK_CLIENT_KEY_LEN +

                      QIO_CHANNEL_WEBSOCK_GUID_LEN + 1];

    char *accept = NULL;

    char *date = qio_channel_websock_date_str();



    g_strlcpy(combined_key, key, QIO_CHANNEL_WEBSOCK_CLIENT_KEY_LEN + 1);

    g_strlcat(combined_key, QIO_CHANNEL_WEBSOCK_GUID,

              QIO_CHANNEL_WEBSOCK_CLIENT_KEY_LEN +

              QIO_CHANNEL_WEBSOCK_GUID_LEN + 1);



    /* hash and encode it */

    if (qcrypto_hash_base64(QCRYPTO_HASH_ALG_SHA1,

                            combined_key,

                            QIO_CHANNEL_WEBSOCK_CLIENT_KEY_LEN +

                            QIO_CHANNEL_WEBSOCK_GUID_LEN,

                            &accept,

                            errp) < 0) {

        qio_channel_websock_handshake_send_res_err(

            ioc, QIO_CHANNEL_WEBSOCK_HANDSHAKE_RES_SERVER_ERR);

        return;

    }



    qio_channel_websock_handshake_send_res(

        ioc, QIO_CHANNEL_WEBSOCK_HANDSHAKE_RES_OK, date, accept);



    g_free(date);

    g_free(accept);

}

