void bdrv_drain_all(void)

{

    /* Always run first iteration so any pending completion BHs run */

    bool busy = true;

    BlockDriverState *bs;



    while (busy) {

        /* FIXME: We do not have timer support here, so this is effectively

         * a busy wait.

