               "Invalid bitstream, too many SBR envelopes in VARVAR type SBR frame: %d\n",
               ch_data->bs_num_env[1]);
        return -1;
    }
    ch_data->bs_num_noise = (ch_data->bs_num_env[1] > 1) + 1;
    return 0;
}

