static int ast_read_packet(AVFormatContext *s, AVPacket *pkt)

{

    uint32_t type, size;

    int64_t pos;

    int ret;



    if (avio_feof(s->pb))

        return AVERROR_EOF;



    pos  = avio_tell(s->pb);

    type = avio_rl32(s->pb);

    size = avio_rb32(s->pb);

    if (size > INT_MAX / s->streams[0]->codecpar->channels)

