        if (ret == 1) {

            AVStream *st = s->streams[pkt->stream_index];

            AVStream *ost = oc->streams[pkt->stream_index];

            st->internal->bsfcs = ost->internal->bsfcs;

            st->internal->nb_bsfcs = ost->internal->nb_bsfcs;

