static int qdm2_get_vlc (GetBitContext *gb, VLC *vlc, int flag, int depth)

{

    int value;



    value = get_vlc2(gb, vlc->table, vlc->bits, depth);



    /* stage-2, 3 bits exponent escape sequence */

    if (value-- == 0)

        value = get_bits (gb, get_bits (gb, 3) + 1);



