        x |= (range_decode_bits(ctx, tmpk - 16) << 16);

    } else {

        av_log(ctx->avctx, AV_LOG_ERROR, "Too many bits: %d\n", tmpk);

        return AVERROR_INVALIDDATA;

    }

    x += overflow << tmpk;



    update_rice(rice, x);



